int findPeakElement_55(const vector<int>& a) { int lo = 0, hi = (int)a.size() - 1; while (lo < hi) { int mid = lo + (hi - lo) / 2; if (a[mid] < a[mid + 1]) lo = mid + 1; else hi = mid; } return lo; }
long long intSquareRootBS_55(long long n) { if (n < 2) return n; long long lo = 1, hi = n, ans = 1; while (lo <= hi) { long long mid = lo + (hi - lo) / 2; if (mid <= n / mid) { ans = mid; lo = mid + 1; } else hi = mid - 1; } return ans; }
int lowerBoundSearch_55(const vector<int>& a, int target) { int lo = 0, hi = (int)a.size(); while (lo < hi) { int mid = lo + (hi - lo) / 2; if (a[mid] >= target) hi = mid; else lo = mid + 1; } return lo; }
int upperBoundSearch_55(const vector<int>& a, int target) { int lo = 0, hi = (int)a.size(); while (lo < hi) { int mid = lo + (hi - lo) / 2; if (a[mid] > target) hi = mid; else lo = mid + 1; } return lo; }
bool isPerfectSquareBS_55(long long n) { if (n < 0) return false; if (n <= 1) return true; long long lo = 1, hi = n; while (lo <= hi) { long long mid = lo + (hi - lo) / 2; if (mid * mid == n) return true; if (mid * mid < n) lo = mid + 1; else hi = mid - 1; } return false; }
